// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        address recipient = address(0x1234);
        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "funding failed");
        vm.prank(address(this));
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
